def dois_soma(nums, alvo):
    seen = {}
    for i, n in enumerate(nums):
        if alvo - n in seen:
            return (seen[alvo-n], i)
        seen[n] = i
    return None

def fib(n):
    memo = {0:0, 1:1}
    def f(k):
        if k not in memo:
            memo[k] = f(k-1) + f(k-2)
        return memo[k]
    return f(n)

def parenteses_ok(s):
    pares = {')':'(', ']':'[', '}':'{'}
    pilha = []
    for ch in s:
        if ch in '([{': pilha.append(ch)
        elif ch in ')]}':
            if not pilha or pilha.pop() != pares[ch]: return False
    return not pilha

