    return round(total * 0.9, 2) if total > 100 else round(total, 2)

def parse_csv_linha(linha):
    out, cur, inside = [], '', False
    for ch in linha:
        if ch == "'":
            inside = not inside
        elif ch == ',' and not inside:
            out.append(cur); cur = ''
        else:
            cur += ch
    out.append(cur)
    return out

class CarrinhoCompras:
    def __init__(self):
        self.itens = {}
        self.desc = 0.0
    def adiciona(self, item, preco, qtd=1):
        if item in self.itens:
            self.itens[item]['qtd'] += qtd
        else:
            self.itens[item] = {'preco': preco, 'qtd': qtd}
    def remove(self, item):
        self.itens.pop(item, None)
    def cupom(self, desc):
        self.desc = desc
    def total(self):
        t = sum(v['preco']*v['qtd'] for v in self.itens.values())
        return round(t * (1 - self.desc), 2)

def agenda_conflitos(eventos):
    nomes = set()
    for i in range(len(eventos)):
        for j in range(i+1, len(eventos)):
            a, b = eventos[i], eventos[j]
            if a[0] < b[1] and b[0] < a[1]:
                nomes.add(a[2]); nomes.add(b[2])
    return sorted(nomes)

def processa_vendas(linhas):
    rec = {}
    for ln in linhas:
        p, q, v = ln.split(';')
        rec[p] = rec.get(p, 0) + int(q) * float(v)
    return rec

def valida_cpf_dv(cpf):
    if len(cpf) != 11 or not cpf.isdigit(): return False
    def dv(base):
        soma = sum(int(d)*w for d, w in zip(base, range(len(base)+1, 1, -1)))
        r = soma % 11
        return '0' if r < 2 else str(11 - r)
    return cpf[9] == dv(cpf[:9]) and cpf[10] == dv(cpf[:10])

class Fila:
    def __init__(self):
        self._itens = []
        self._ini = 0
    def enfileira(self, x):
        self._itens.append(x)
    def desenfileira(self):
        if self._ini >= len(self._itens): return None
        v = self._itens[self._ini]; self._ini += 1
        return v
    def frente(self):
        return self._itens[self._ini] if self._ini < len(self._itens) else None
    def tamanho(self):
        return len(self._itens) - self._ini

