class Cache:
    def __init__(self, limite):
        from collections import OrderedDict
        self.limite = limite
        self.d = OrderedDict()
    def get(self, k):
        if k not in self.d: return None
        self.d.move_to_end(k)
        return self.d[k]
    def put(self, k, v):
        self.d[k] = v
        self.d.move_to_end(k)
        if len(self.d) > self.limite:
            self.d.popitem(last=False)

def agrupa_anagramas(palavras):
    from collections import defaultdict
    g = defaultdict(list)
    for p in palavras:
        g[''.join(sorted(p))].append(p)
    return [sorted(v) for v in g.values()]

def intervalos_mesclados(intervalos):
    if not intervalos: return []
    ev = sorted(intervalos)
    out = [list(ev[0])]
    for s, e in ev[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return [tuple(x) for x in out]

class Banco:
    def __init__(self):
        self.contas = {}
    def abrir(self, nome):
        self.contas.setdefault(nome, 0.0)
    def depositar(self, nome, v):
        if nome not in self.contas: return False
        self.contas[nome] += v
        return True
    def sacar(self, nome, v):
        if nome not in self.contas or v > self.contas[nome]:
            return False
        self.contas[nome] -= v
        return True
    def saldo(self, nome):
        return self.contas.get(nome)

def menor_janela(s, t):
    from collections import Counter
    need, falta = Counter(t), len(t)
    i = ini = fim = 0
    melhor = float('inf')
    for j, ch in enumerate(s):
        if need[ch] > 0: falta -= 1
        need[ch] -= 1
        if falta == 0:
            while need[s[i]] < 0:
                need[s[i]] += 1; i += 1
            if j - i < melhor - (fim - ini):
                ini, fim = i, j + 1; melhor = fim - ini
        need.setdefault(s[i] if i < len(s) else '', 0)
    return s[ini:fim] if falta == 0 or melhor != float('inf') else (s[ini:fim] if melhor != float('inf') else '')

def topo_sort(grafo):
    from collections import deque
    grau = {v: 0 for v in grafo}
    for v, ds in grafo.items():
        for d in ds:
            grau[d] = grau.get(d, 0) + 1
    fila = deque([v for v in grafo if grau[v] == 0])
    out = []
    while fila:
        v = fila.popleft(); out.append(v)
        for d in grafo[v]:
            grau[d] -= 1
            if grau[d] == 0: fila.append(d)
    return out if len(out) == len(grau) else []

class Motor:
    def __init__(self, inicial):
        self.estado = inicial
        self.t = {}
    def add(self, estado, evento, proximo):
        self.t[(estado, evento)] = proximo
    def dispara(self, evento):
