def avalia_expr(tokens):
    pilha = []
    for tk in tokens:
        if tk in '+-*/':
            b, a = pilha.pop(), pilha.pop()
            if tk == '+': pilha.append(a + b)
            elif tk == '-': pilha.append(a - b)
            elif tk == '*': pilha.append(a * b)
            else: pilha.append(int(a / b))
        else:
            pilha.append(int(tk))
    return pilha[0]

class EventBus:
    def __init__(self):
        self.h = {}
    def on(self, ev, fn):
        self.h.setdefault(ev, []).append(fn)
    def off(self, ev, fn):
        if ev in self.h and fn in self.h[ev]:
            self.h[ev].remove(fn)
    def emit(self, ev, dado=None):
        for fn in list(self.h.get(ev, [])):
            fn(dado)

