    parcela = total * (1 + 0.02 * n) / n
    return round(parcela, 2)

class Pipeline:
    def __init__(self):
        self.passos = []
    def add(self, nome, fn):
        self.passos.append((nome, fn))
        return self
    def run(self, dado):
        for _, fn in self.passos:
            dado = fn(dado)
        return dado
